import{_ as o,r as a,o as l,c,e,a as p,s as i}from"./chunks/framework.CXcwiNg-.js";const b=JSON.parse('{"title":"Resources - October CMS - 4.x","titleTemplate":false,"description":"Inject assets, variables and headers to the page.","frontmatter":{"subtitle":"Inject assets, variables and headers to the page."},"headers":[{"level":2,"title":"Available Properties","slug":"available-properties","link":"#available-properties","children":[]},{"level":2,"title":"Basic Usage","slug":"basic-usage","link":"#basic-usage","children":[]},{"level":2,"title":"Injecting Variables","slug":"injecting-variables","link":"#injecting-variables","children":[]},{"level":2,"title":"Injecting Assets","slug":"injecting-assets","link":"#injecting-assets","children":[]},{"level":2,"title":"Injecting JavaScript Modules","slug":"injecting-javascript-modules","link":"#injecting-javascript-modules","children":[]},{"level":2,"title":"Using Custom Headers","slug":"using-custom-headers","link":"#using-custom-headers","children":[]}],"relativePath":"4.x/cms/components/resources.md","filePath":"4.x/cms/components/resources.md"}'),r={name:"4.x/cms/components/resources.md"};function u(d,s,g,k,h,v){const n=a("pre-heading"),t=a("post-heading");return l(),c("div",null,[e(n),s[0]||(s[0]=p("h1",null,"Resources",-1)),e(t),s[1]||(s[1]=i(`<p>The <code>resources</code> component can create new variables, add headers and inject assets to the page. The resources component can be used on any page, layout or partial.</p><h2 id="available-properties"><a href="#available-properties" class="header-anchor">#</a> Available Properties</h2><p>The following properties are supported by the component.</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>js</strong></td><td>Array of JavaScript files in the theme <strong>assets/js</strong> folder</td></tr><tr><td><strong>module</strong></td><td>Array of JavaScript module files in the theme <strong>assets/js</strong> folder</td></tr><tr><td><strong>less</strong></td><td>Array of LESS files in the theme <strong>assets/less</strong> folder</td></tr><tr><td><strong>scss</strong></td><td>Array of SCSS files in the theme <strong>assets/scss</strong> folder</td></tr><tr><td><strong>css</strong></td><td>Array of Stylesheet files in the theme <strong>assets/css</strong> folder</td></tr><tr><td><strong>vars</strong></td><td>Includes variables available on the page or layout.</td></tr><tr><td><strong>headers</strong></td><td>Includes headers with the page response.</td></tr></tbody></table></div><h2 id="basic-usage"><a href="#basic-usage" class="header-anchor">#</a> Basic Usage</h2><p>The following example uses the <code>vars</code> property to create a new variable called <strong>activeNav</strong> and this variable becomes available to the page life-cycle, this includes layouts for that page or partials that are used on the page. The variable is accessed using the <code>{{ activeNav }}</code> Twig variable.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">resources</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">vars[activeNav]</span> <span class="token punctuation">=</span> <span class="token value attr-value">&#39;<span class="token inner-value">blog</span>&#39;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">if</span> activeNav <span class="token operator">==</span> <span class="token string"><span class="token punctuation">&#39;</span>blog<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>The blog is active!<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endif</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div></div><h2 id="injecting-variables"><a href="#injecting-variables" class="header-anchor">#</a> Injecting Variables</h2><p>The resources component lets you define any number of variables on the page. These become available to the layout as a usual Twig variable.</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">resources</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">vars[activeNav]</span> <span class="token punctuation">=</span> <span class="token value attr-value">&#39;<span class="token inner-value">blog</span>&#39;</span>
</code></pre></div><p>You may also use parameters from the page cycle. In the following example the <code>activeNav</code> variable will contain the value found inside the <code>:slug</code> page route.</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">mypage/:slug</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">resources</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">vars[activeNav]</span> <span class="token punctuation">=</span> <span class="token value attr-value">&#39;<span class="token inner-value">{{ :slug }}</span>&#39;</span>
</code></pre></div><p>This concept also works for component variables. The following example looks up the author by the <code>:slug</code> found in the page route and then assigns the <code>author.id</code> to the <strong>authorIdPage</strong> page variable.</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/author/:slug</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">section author</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">handle</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Blog\\Author</span>&quot;</span>
<span class="token key attr-name">identifier</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">slug</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">resources</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">vars[authorIdPage]</span> <span class="token punctuation">=</span> <span class="token value attr-value">&#39;<span class="token inner-value">Author ID is: {{ author.id }}</span>&#39;</span>
</code></pre></div><h2 id="injecting-assets"><a href="#injecting-assets" class="header-anchor">#</a> Injecting Assets</h2><p>If a layout includes the standard <code>{% scripts %}</code> and <code>{% styles %}</code> tags, then it is possible to inject assets to these placeholders. The assets will be bundled and combined to a single script/style reference.</p><p>Assets loaded using the resources component should be in a specific folder inside the theme as described in the available properties. An example could be a partial named <strong>blocks/carousel.htm</strong></p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">resources</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">css[]</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">blocks/carousel.css</span>&quot;</span>
<span class="token key attr-name">scss[]</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">blocks/carousel.scss</span>&quot;</span>
<span class="token key attr-name">less[]</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">blocks/carousel.less</span>&quot;</span>
<span class="token key attr-name">js[]</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">blocks/carousel.js</span>&quot;</span>
</code></pre></div><div class="language-html extra-class"><pre class="language-html"><code><span class="token comment">&lt;!-- Carousel Contents Here --&gt;</span>
</code></pre></div></div><p>Now when the partial is loaded on the page, the scripts and stylesheets will be injected to the layout. The assets should be located in the <strong>assets/js/blocks/carousel.js</strong> and <strong>assets/less/blocks/carousel.less</strong> directories respectively.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token comment">&lt;!-- Assets for the carousel are injected automatically --&gt;</span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&#39;</span>blocks/carousel<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><div class="custom-block tip"><p>Using the partial twice on the page will only inject the assets once.</p></div><h2 id="injecting-javascript-modules"><a href="#injecting-javascript-modules" class="header-anchor">#</a> Injecting JavaScript Modules</h2><p>The <code>module</code> property includes JavaScript files as ES modules. Unlike the <code>js</code> property which bundles and combines scripts, module files are served individually with <code>type=&quot;module&quot;</code> on the script tag. This is useful for loading ESM entry points that use <code>import</code> statements.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">resources</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">module[]</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">app.js</span>&quot;</span>
</code></pre></div><div class="language-html extra-class"><pre class="language-html"><code><span class="token comment">&lt;!-- Page Contents Here --&gt;</span>
</code></pre></div></div><p>The module file should be located at <strong>assets/js/app.js</strong> and can use standard ESM imports to load other modules.</p><div class="language-js extra-class"><pre class="language-js"><code><span class="token keyword">import</span> <span class="token punctuation">{</span> initCarousel <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;./controls/carousel.js&#39;</span><span class="token punctuation">;</span>

<span class="token function">initCarousel</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>You can use <code>module</code> alongside <code>js</code> on the same page. The <code>js</code> assets will be bundled as usual, while <code>module</code> assets are loaded as separate ES modules.</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">resources</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">js[]</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">legacy-script.js</span>&quot;</span>
<span class="token key attr-name">module[]</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">app.js</span>&quot;</span>
</code></pre></div><h2 id="using-custom-headers"><a href="#using-custom-headers" class="header-anchor">#</a> Using Custom Headers</h2><p>As an example of defining custom headers, you may wish to render XML content on a page instead of HTML content. This is possible by injecting a <code>Content-Type</code> header in to the page and giving it a value of <strong>text/xml</strong>. This header value will be sent with the response when the page loads.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog/rss</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">resources</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">headers[Content-Type]</span> <span class="token punctuation">=</span> <span class="token value attr-value">&#39;<span class="token inner-value">text/xml</span>&#39;</span>
</code></pre></div><div class="language-xml extra-class"><pre class="language-xml"><code><span class="token prolog">&lt;?xml version=&quot;1.0&quot; encoding=&quot;utf-8&quot;?&gt;</span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>rss</span> <span class="token attr-name">version</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>2.0<span class="token punctuation">&quot;</span></span> <span class="token attr-name"><span class="token namespace">xmlns:</span>atom</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>http://www.w3.org/2005/Atom<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token comment">&lt;!-- RSS contents here --&gt;</span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>rss</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div>`,31))])}const y=o(r,[["render",u]]);export{b as __pageData,y as default};
